import{_ as a,c as e,o as t,a4 as s}from"./chunks/framework.iMXuyU9c.js";const g=JSON.parse('{"title":"电脑休眠自动重启的解决办法","description":"","frontmatter":{},"headers":[],"relativePath":"Windows_About/电脑休眠自动重启的解决办法.md","filePath":"Windows_About/电脑休眠自动重启的解决办法.md"}'),o={name:"Windows_About/电脑休眠自动重启的解决办法.md"},i=s(`<h1 id="电脑休眠自动重启的解决办法" tabindex="-1">电脑休眠自动重启的解决办法 <a class="header-anchor" href="#电脑休眠自动重启的解决办法" aria-label="Permalink to &quot;电脑休眠自动重启的解决办法&quot;">​</a></h1><pre><code>该文创建于 2024/11/28    文章参考
</code></pre><p><a href="https://zhuanlan.zhihu.com/p/147456304" target="_blank" rel="noreferrer">zhangzc.知乎</a></p><h2 id="休眠指令" tabindex="-1">休眠指令 <a class="header-anchor" href="#休眠指令" aria-label="Permalink to &quot;休眠指令&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shutdown -h</span></span></code></pre></div><h2 id="表现" tabindex="-1">表现 <a class="header-anchor" href="#表现" aria-label="Permalink to &quot;表现&quot;">​</a></h2><p>当时给电脑休眠，我也准备休眠，快睡着了电脑突然转风扇了(声音有点大……),就又给电脑鼠标一翻再次休眠了我继续睡 第二天起来发现电脑又是工作状态…… 休眠!然后发现基本是整点唤醒!所以应该是电脑有什么定时计划吧电脑唤醒了(之前鼠标翻过来了,不可能是键鼠移动造成的)</p><h2 id="解决" tabindex="-1">解决 <a class="header-anchor" href="#解决" aria-label="Permalink to &quot;解决&quot;">​</a></h2><p>参照[zhangzc.知乎]的文章,我没有直接去查[计算机管理]的任务,而是先查了一下该文章底部的命令提示符(CMD)指令</p><div class="language-CMD vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">CMD</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powercfg /lastwake</span></span></code></pre></div><p>结果如图,是什么 &quot;Realtek PCIe GBE Family Controller&quot; <img src="" alt="" loading="lazy">百度一查,是我的网卡,然后&#39;此电脑&#39;--右键--&gt;&#39;管理&#39;----&gt;&#39;设备管理器&#39;----&gt;网络适配器,把网卡的属性里的&#39;允许此设备唤醒计算机&#39;一关,搞定!</p>`,11),n=[i];function r(l,c,h,d,p,_){return t(),e("div",null,n)}const b=a(o,[["render",r]]);export{g as __pageData,b as default};
